# N = 3 replicas per key; strong reads when R + W > N
N, W, R = 3, 2, 2   # 2 + 2 = 4 > 3 -> strong consistency for the key

def put(key, value):
    version = next_version(key)          # timestamp or version vector
    acks = 0
    for replica in replicas_for(key):    # send to all N
        if replica.store(key, value, version):
            acks += 1
    if acks >= W:
        return OK                        # durable on W replicas
    raise QuorumNotMet()                  # could not reach write quorum

def get(key):
    responses = []
    for replica in replicas_for(key):     # query all N
        r = replica.fetch(key)
        if r: responses.append(r)
        if len(responses) >= R: break
    if len(responses) < R:
        raise QuorumNotMet()
    latest = max(responses, key=lambda r: r.version)
    # read repair: push the latest version back to any stale replica
    for replica in replicas_for(key):
        if replica.version_of(key) < latest.version:
            replica.store(key, latest.value, latest.version)
    return latest.value
